package in.jharkhand.civic.controller;
import in.jharkhand.civic.service.AuthService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final AuthService auth;public AuthController(AuthService a){auth=a;} record Login(@Email @NotBlank String email,@NotBlank String password){} record Register(@NotBlank String name,@Email @NotBlank String email,@Size(min=6,max=100) String password,String language){} @PostMapping("/login") public Map<String,Object> login(@Valid @RequestBody Login r){return auth.login(r.email(),r.password());}@PostMapping("/register") public Map<String,Object> register(@Valid @RequestBody Register r){return auth.register(r.name(),r.email(),r.password(),r.language());}@GetMapping("/me") public Map<String,Object> me(Authentication a){return auth.me(a.getName());}}
